import { test, expect } from '@playwright/test'

test.describe('Login flow', () => {
  test('successful login redirects to the dashboard', async ({ page }) => {
    await page.goto('http://localhost:3000/login')

    await page.getByLabel('Email').fill('user@example.com')
    await page.getByLabel('Password').fill('secure-password')
    await page.getByRole('button', { name: /sign in/i }).click()

    await expect(page).toHaveURL('http://localhost:3000/dashboard')
    await expect(page.getByRole('heading', { name: /dashboard/i }))
      .toBeVisible()
  })

  test('shows an error message for invalid credentials', async ({ page }) => {
    await page.goto('http://localhost:3000/login')

    await page.getByLabel('Email').fill('wrong@example.com')
    await page.getByLabel('Password').fill('wrong-password')
    await page.getByRole('button', { name: /sign in/i }).click()

    await expect(page.getByRole('alert')).toHaveText('Invalid email or password')
  })
})

import { test as base } from '@playwright/test'

export const test = base.extend({
  // Run once per worker, not once per test.
  storageState: { path: 'playwright/.auth/admin.json' },
})

test('admin can access the settings page', async ({ page, storageState }) => {
  await page.goto('http://localhost:3000/admin/settings')
  await expect(page.getByRole('heading', { name: /settings/i })).toBeVisible()
})
